const Q_META = [
  {id:"Q1_책임과 사명", title:"책임과 사명", sub:"무거운 걸 짊어질 때 나는"},
  {id:"Q2_감정을 다루는 방식", title:"감정을 다루는 방식", sub:"마음이 흔들릴 때 나는"},
  {id:"Q3_관계 맺는 방식", title:"관계 맺는 방식", sub:"사람과 함께일 때 나는"},
  {id:"Q4_나를 보는 시선", title:"나를 보는 시선", sub:"스스로를 볼 때 나는"},
  {id:"Q5_행동하는 방식", title:"행동하는 방식", sub:"무언가에 부딪힐 때 나는"},
];
const MAX_PICK = 5;
const TOP_SHOW = 9;

let qIndex = 0;
let picks = [[],[],[],[],[]];
let expanded = [false,false,false,false,false];
let freeText = "";
let matchedHero = null;
let matchedKeywords = [];

function el(id){ return document.getElementById(id); }
function setNL(s){ return s.split("{{NEWLINE}}").join("\n"); }
document.querySelectorAll('.headline,.q-title,.reveal-headline,.quote-block').forEach(n=>{
  n.innerHTML = n.innerHTML.split("{{NEWLINE}}").join("<br>");
});

function goToStep(name, qi){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  if(name==='question'){
    qIndex = qi;
    renderQuestion();
    el('screen-question').classList.add('active');
  } else {
    el('screen-'+name).classList.add('active');
  }
  window.scrollTo(0,0);
}

function goStart(){ goToStep('question', 0); }

function renderQuestion(){
  const meta = Q_META[qIndex];
  const cat = KEYWORDS.categories.find(c=>c.id===meta.id);
  const sortedCanon = cat.canon.slice().sort((a,b)=> (KEYWORDS.counts[b]||0)-(KEYWORDS.counts[a]||0));
  const sel = picks[qIndex];

  el('qProgress').innerHTML = Q_META.map((_,i)=>`<i class="${i<=qIndex?'done':''}"></i>`).join('');
  el('qCat').textContent = `질문 ${qIndex+1} / ${Q_META.length}`;
  el('qTitle').textContent = meta.title;
  el('qSub').textContent = `${meta.sub} — 최대 ${MAX_PICK}개까지 골라주세요`;

  const showList = expanded[qIndex] ? sortedCanon : sortedCanon.slice(0, TOP_SHOW);
  el('qChips').innerHTML = showList.map(w=>{
    const on = sel.includes(w);
    return `<button class="chip ${on?'on':''}" data-word="${w}">${w}</button>`;
  }).join('');
  document.querySelectorAll('#qChips .chip').forEach(btn=>{
    btn.onclick = ()=>{
      const w = btn.getAttribute('data-word');
      const idx = sel.indexOf(w);
      if(idx>-1) sel.splice(idx,1);
      else if(sel.length < MAX_PICK) sel.push(w);
      renderQuestion();
    };
  });

  const moreBtn = el('qMoreBtn');
  if(sortedCanon.length > TOP_SHOW){
    moreBtn.style.display = 'inline-block';
    moreBtn.textContent = expanded[qIndex] ? '접기' : `숨은 키워드 더 보기 (${sortedCanon.length - TOP_SHOW})`;
    moreBtn.onclick = ()=>{ expanded[qIndex] = !expanded[qIndex]; renderQuestion(); };
  } else {
    moreBtn.style.display = 'none';
  }

  el('qBackBtn').style.visibility = qIndex===0 ? 'hidden' : 'visible';
  el('qBackBtn').onclick = ()=>{
    if(qIndex===0) return;
    goToStep('question', qIndex-1);
  };
  const nextBtn = el('qNextBtn');
  nextBtn.disabled = sel.length===0;
  nextBtn.textContent = qIndex === Q_META.length-1 ? '다음' : '다음';
  nextBtn.onclick = ()=>{
    if(qIndex === Q_META.length-1){
      goToStep('freetext');
    } else {
      goToStep('question', qIndex+1);
    }
  };
}

const LOADING_PHRASES = [
  "50년의 기록을 살펴보는 중",
  "49개 시리즈, 310명의 영웅을 탐색하는 중",
  "당신과 같은 약점을 지녔던 이를 찾는 중",
  "그 영웅이 그 약점을 어떻게 안고 살았는지 확인하는 중",
];

function startMatching(){
  freeText = el('freeTextInput').value.trim();
  goToStep('loading');
  let i = 0;
  el('loadingText').textContent = LOADING_PHRASES[0];
  const interval = setInterval(()=>{
    i++;
    if(i < LOADING_PHRASES.length){
      el('loadingText').style.opacity = 0;
      setTimeout(()=>{
        el('loadingText').textContent = LOADING_PHRASES[i];
        el('loadingText').style.opacity = 1;
      }, 300);
    }
  }, 850);
  setTimeout(()=>{
    clearInterval(interval);
    runMatch();
    showResult();
  }, 850*LOADING_PHRASES.length + 400);
}

function runMatch(){
  const selected = picks.flat();
  let best = [];
  let bestScore = -1;
  RANGERS.forEach(r=>{
    const wSet = r.weaknessCanon || [];
    const pSet = r.personalityCanon || [];
    let score = 0;
    selected.forEach(k=>{
      if(wSet.includes(k)) score += 2;
      if(pSet.includes(k)) score += 1;
    });
    if(score > bestScore){ bestScore = score; best = [r]; }
    else if(score === bestScore){ best.push(r); }
  });
  if(bestScore <= 0){
    matchedHero = RANGERS[Math.floor(Math.random()*RANGERS.length)];
  } else {
    matchedHero = best[Math.floor(Math.random()*best.length)];
  }
  const wSet = matchedHero.weaknessCanon || [];
  const pSet = matchedHero.personalityCanon || [];
  matchedKeywords = selected.filter(k=> wSet.includes(k) || pSet.includes(k));
  matchedKeywords = [...new Set(matchedKeywords)];
}

const COLOR_MAP = {
  "레드":"#c94b32","블루":"#3a6fb0","옐로":"#d9a72c","그린":"#4a8f5c","핑크":"#c9698f",
  "블랙":"#3a3a3d","화이트":"#d8d5cb","골드":"#c9a24b","실버":"#9a9a9d","오렌지":"#d9722c",
  "바이올렛":"#7a5aa8","시안":"#4ab0c9","그레이":"#7d7d7f","브라운":"#8a6a4a"
};
function colorFor(name){
  for(const k in COLOR_MAP){ if(name && name.includes(k)) return COLOR_MAP[k]; }
  return "#c94b32";
}

function showResult(){
  const c = colorFor(matchedHero.color);
  el('heroColorDot').style.background = c;
  el('heroName1').textContent = matchedHero.name;
  el('heroName1').style.color = c;
  el('heroSeries1').textContent = `${matchedHero.series} · ${matchedHero.color}`;

  el('matchKeywords').innerHTML = matchedKeywords.length
    ? matchedKeywords.map(k=>`<span class="kw-pill">${k}</span>`).join('')
    : '<span class="kw-pill">고요함 속의 결단</span>';

  const desc = matchedHero.summary || matchedHero.description || "";
  const longDesc = matchedHero.description || "";
  el('heroDesc').innerHTML = `<b>${matchedHero.name}</b> — ${desc}${longDesc && longDesc!==desc ? '<br><br>'+longDesc : ''}`;

  el('userQuoteEcho').textContent = freeText ? `"${freeText}" — 그 이야기는, 멸종된 게 아니라 아직 완성되지 않은 것입니다.` : "";

  goToStep('result1');
}

function saveToArchive(){
  const record = {
    ts: Date.now(),
    heroName: matchedHero.name,
    heroSeries: matchedHero.series,
    heroColor: matchedHero.color,
    userKeywords: picks.flat(),
    matchedKeywords: matchedKeywords,
    freeText: freeText,
  };
  const key = 'projectR_archive';
  const arr = JSON.parse(localStorage.getItem(key) || '[]');
  arr.push(record);
  localStorage.setItem(key, JSON.stringify(arr));
  el('savedFlag').style.display = 'block';
}

function exportImage(){
  const canvas = el('exportCanvas');
  const ctx = canvas.getContext('2d');
  const c = colorFor(matchedHero.color);
  ctx.fillStyle = '#0b0b0d';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.strokeStyle = 'rgba(255,255,255,0.14)';
  ctx.lineWidth = 2;
  ctx.strokeRect(40,40,canvas.width-80,canvas.height-80);

  ctx.fillStyle = '#706e68';
  ctx.font = '28px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('PROJECT.R · 수호 영웅 찾기', canvas.width/2, 140);

  ctx.fillStyle = c;
  ctx.beginPath();
  ctx.arc(canvas.width/2, 240, 16, 0, Math.PI*2);
  ctx.fill();

  ctx.fillStyle = c;
  ctx.font = '600 72px serif';
  wrapText(ctx, matchedHero.name, canvas.width/2, 340, 900, 80);

  ctx.fillStyle = '#a6a49c';
  ctx.font = '26px sans-serif';
  ctx.fillText(matchedHero.series + ' · ' + matchedHero.color, canvas.width/2, 430);

  ctx.fillStyle = '#f2f0ea';
  ctx.font = '30px serif';
  wrapText(ctx, '"멸종된 것은 파워레인저가 아니라,\n어쩌면 당신 안의 영웅성이었을지도 모릅니다."', canvas.width/2, 620, 820, 46);

  ctx.fillStyle = '#c94b32';
  ctx.font = '24px sans-serif';
  let kwLine = matchedKeywords.slice(0,4).join('   ·   ');
  ctx.fillText(kwLine, canvas.width/2, 900);

  ctx.fillStyle = '#706e68';
  ctx.font = '20px sans-serif';
  ctx.fillText('50년, 49개 시리즈, 310명의 기록에서 찾은 이야기', canvas.width/2, canvas.height-100);

  const link = document.createElement('a');
  link.download = `project-r_${matchedHero.name}.png`;
  link.href = canvas.toDataURL('image/png');
  link.click();
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight){
  const paragraphs = text.split('\n');
  let curY = y;
  paragraphs.forEach(par=>{
    const words = par.split('');
    let line = '';
    const lines = [];
    words.forEach(ch=>{
      const test = line + ch;
      if(ctx.measureText(test).width > maxWidth && line){
        lines.push(line);
        line = ch;
      } else {
        line = test;
      }
    });
    lines.push(line);
    lines.forEach(l=>{ ctx.fillText(l.trim(), x, curY); curY += lineHeight; });
  });
}

function restart(){
  qIndex = 0;
  picks = [[],[],[],[],[]];
  expanded = [false,false,false,false,false];
  freeText = "";
  matchedHero = null;
  matchedKeywords = [];
  el('freeTextInput').value = '';
  el('savedFlag').style.display = 'none';
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  el('screen-intro').classList.add('active');
  window.scrollTo(0,0);
}
